const DEFAULT_APP = 'https://urbanfold.github.io/property-survey/';
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
function response(body,status,origin) {
 const headers={'Content-Type':'application/json','Cache-Control':'no-store'};
 if(origin)Object.assign(headers,{'Access-Control-Allow-Origin':origin,'Vary':'Origin',
  'Access-Control-Allow-Headers':'authorization,apikey,content-type,x-client-info','Access-Control-Allow-Methods':'POST,OPTIONS'});
 return new Response(JSON.stringify(body),{status,headers});
}
async function parsed(r){try{return await r.json();}catch{return null;}}
async function smallBody(request){
 const reader=request.body?.getReader();if(!reader)return {};
 let total=0;const chunks=[];
 try{while(true){const {done,value}=await reader.read();if(done)break;total+=value.byteLength;if(total>4096){await reader.cancel();throw Error('large');}chunks.push(value);}}
 finally{reader.releaseLock();}
 const bytes=new Uint8Array(total);let offset=0;for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.byteLength;}
 return JSON.parse(new TextDecoder().decode(bytes));
}
export async function requestSurveyNotification(request,{env,fetcher=fetch}){
 let app;
 try{app=new URL(env('APP_URL')||DEFAULT_APP);if(app.protocol!=='https:'||app.search||app.hash)throw Error();}
 catch{return response({error:'Notification service is not configured.'},503);}
 const origin=request.headers.get('origin');
 if(origin&&origin!==app.origin)return response({error:'Origin not permitted.'},403);
 const cors=origin===app.origin?origin:null;
 if(request.method==='OPTIONS')return response({},200,app.origin);
 if(request.method!=='POST')return response({error:'Method not allowed.'},405,cors);
 const authorization=request.headers.get('authorization')||'';
 if(!/^Bearer \S+$/.test(authorization))return response({error:'Sign in to request a notification.'},401,cors);
 const base=env('SUPABASE_URL'),anon=env('SUPABASE_ANON_KEY'),service=env('SUPABASE_SERVICE_ROLE_KEY');
 let hook;
 try{hook=new URL(env('SURVEY_NOTIFICATION_WEBHOOK_URL'));if(hook.protocol!=='https:'||hook.hostname!=='hooks.zapier.com'||!hook.pathname.startsWith('/hooks/catch/'))throw Error();}
 catch{return response({error:'Your survey is saved; notifications are not configured yet.'},503,cors);}
 if(!base||!anon||!service)return response({error:'Notification service is not configured.'},503,cors);
 const headers={apikey:anon,authorization,'Content-Type':'application/json'};
 const serverHeaders={apikey:service,Authorization:'Bearer '+service,'Content-Type':'application/json'};
 let claim;
 try{
  const auth=await fetcher(base+'/auth/v1/user',{headers,signal:AbortSignal.timeout(10000)});
  const user=await parsed(auth);
  if(!auth.ok||!UUID.test(user?.id||'')||!user.email_confirmed_at)return response({error:'Sign in with a confirmed account.'},401,cors);
  let body;try{body=await smallBody(request);}catch{return response({error:'Invalid notification request.'},400,cors);}
  if(typeof body?.property_id!=='string'||!UUID.test(body.property_id)||Object.keys(body).some(key=>key!=='property_id'))return response({error:'Only a property ID may be submitted.'},400,cors);
  const propertyResponse=await fetcher(base+'/rest/v1/properties?select=id,last_submitted_at&id=eq.'+body.property_id,{headers,signal:AbortSignal.timeout(10000)});
  const properties=await parsed(propertyResponse);
  if(!propertyResponse.ok||!Array.isArray(properties)||properties.length!==1)return response({error:'Survey is unavailable.'},403,cors);
  const property=properties[0];if(!property.last_submitted_at)return response({error:'Submit and save the survey first.'},409,cors);
  const claimed=await fetcher(base+'/rest/v1/rpc/claim_survey_notification',{method:'POST',headers:serverHeaders,
   body:JSON.stringify({actor:user.id,property:body.property_id,revision:property.last_submitted_at}),signal:AbortSignal.timeout(10000)});
  claim=await parsed(claimed);
  if(!claimed.ok){
   const code=claim?.message;
   const status=code==='NOTIFICATION_RATE_LIMIT'?429:code==='NOTIFICATION_NOT_ALLOWED'||code==='NOTIFICATION_AUTH_REQUIRED'?403:409;
   return response({error:status===429?'Notification limit reached. Do not resubmit just to retry email.':'Notification could not be requested for this saved submission.'},status,cors);
  }
  if(!UUID.test(claim?.id||''))throw Error('Invalid claim');
  if(!claim.claimed)return response({status:claim.state==='accepted'?'accepted':'uncertain'},claim.state==='accepted'?200:202,cors);
  if(claim.payload?.property_id!==body.property_id)throw Error('Invalid payload');
  const hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(claim.id));
  const submission_id=Array.from(new Uint8Array(hash),b=>b.toString(16).padStart(2,'0')).join('');
  let accepted=false;
  try{
   const sent=await fetcher(hook.href,{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':claim.id},
    body:JSON.stringify({...claim.payload,submission_id}),signal:AbortSignal.timeout(10000)});
   accepted=sent.ok;
  }catch{/* Ambiguous delivery: record uncertain and do not automatically resend. */}
  const finish=await fetcher(base+'/rest/v1/rpc/finish_survey_notification',{method:'POST',headers:serverHeaders,
   body:JSON.stringify({event:claim.id,accepted}),signal:AbortSignal.timeout(10000)});
  if(!finish.ok)return response({status:'uncertain'},202,cors);
  return response({status:accepted?'accepted':'uncertain'},accepted?200:202,cors);
 }catch{return response({status:'uncertain',error:'Survey saved; notification could not be confirmed. Do not resubmit just to retry email.'},503,cors);}
}

Deno.serve((request) => requestSurveyNotification(request, { env: (name) => Deno.env.get(name) }));
